import React from "react";
import { Navbar, Nav, NavItem, NavLink } from "reactstrap";
import { Link, useNavigate } from "react-router-dom";
import { useDispatch, useSelector } from "react-redux";
import { logout } from "../Features/UserSlice";
import "../Styles/Header.css";

const Header = () => {
  const dispatch = useDispatch();
  const navigate = useNavigate();
  const { user } = useSelector((state) => state.users);

  // 🔹 Logout نفس أسلوب الأستاذة
  const handleLogout = async () => {
    dispatch(logout());
    await new Promise((resolve) => setTimeout(resolve, 100));
    navigate("/login");
  };

  return (
    <>
      <Navbar className="header">
        <Nav>
          {/* ✅ الشعار */}
          <NavItem>
            <div className="brand">
              <div className="logo-circle">UL</div>
              <div className="brand-text">
                <span className="brand-main">UTAS</span>
                <span className="brand-accent">Link</span>
              </div>
            </div>
          </NavItem>

          {/* الصفحة الرئيسية */}
          <NavItem>
            <Link to="/">Home</Link>
          </NavItem>

          {/* 👩‍🎓 روابط الطالب */}
          {user?.role === "student" && (
            <>
              <NavItem>
                <Link to="/findjob">Find Job</Link>
              </NavItem>

              <NavItem>
                <Link to="/myapplications">My Applications</Link>
              </NavItem>

              <NavItem>
                <Link to="/userprofile">Profile</Link>
              </NavItem>

              <NavItem>
                <NavLink onClick={handleLogout}>Logout</NavLink>
              </NavItem>
            </>
          )}

          {/* 🏢 روابط الشركة */}
          {user?.role === "company" && (
            <>
              <NavItem>
                <Link to="/companyprofile">Company Profile</Link>
              </NavItem>

              <NavItem>
                <Link to="/postjob">Post Job</Link>
              </NavItem>

              <NavItem>
                <Link to="/companyjobs">My Jobs</Link>
              </NavItem>

              <NavItem>
                <Link to="/applicantsjob">Applicants</Link>
              </NavItem>

              <NavItem>
                <Link to="/chatpage">Chat</Link>
              </NavItem>

              <NavItem>
                <NavLink onClick={handleLogout}>Logout</NavLink>
              </NavItem>
            </>
          )}

          {/* 🚪 المستخدم غير المسجل */}
          {!user?.email && (
            <>
              <NavItem>
                <Link to="/login">Login</Link>
              </NavItem>

              <NavItem>
                <Link to="/user-register">Register</Link>
              </NavItem>
            </>
          )}
        </Nav>
      </Navbar>
    </>
  );
};

export default Header;
